from pathlib import Path
from html import escape as e
import json, hashlib

ROOT=Path(__file__).resolve().parent
SITE=ROOT.parent/'bar-site'
D=json.loads((SITE/'menu.json').read_text())
def price(v):return ('–'.join(map(str,v)) if isinstance(v,list) else str(v))+' ₽'
def image_path(item):
    img=item['image']
    return 'assets/'+img if img.endswith(('.svg','.jpg','.jpeg','.png','.webp')) else 'assets/'+img+'.webp'
def nutrients(item):
    v=item['nutrition']['values']
    if not v:return '<div class="nutrition pending">КБЖУ уточняются по '+('рецептуре' if item['id']=='fruit-tea' else 'этикетке')+'</div>'
    return f'<div class="nutrition"><strong>≈{v["kcal"]} ккал</strong><div class="macro-line"><span>Б {v["protein"]} г</span><span>Ж {v["fat"]} г</span><span>У {v["carbs"]} г</span></div></div>'
def detail(item):
    return f'<button class="detail-button" type="button" data-details="{item["id"]}" aria-haspopup="dialog" aria-label="Состав и КБЖУ: {e(item["name"])}"><span class="detail-desktop">Подробнее</span><span class="detail-mobile">Состав и КБЖУ</span><span aria-hidden="true">↗</span></button>'
def card(item):
    badge=f'<span class="card-badge">{e(item["badge"])}</span>' if item['badge'] else ''
    volume=f'<span class="card-volume">{item["volume_ml"]} мл</span>' if item['volume_ml'] else ''
    image_dimensions = 'width="1122" height="1402"'
    return (f'<article class="drink-card" data-menu-item="{item["id"]}"><button class="drink-image" type="button" data-details="{item["id"]}" aria-label="Подробнее: {e(item["name"])}" aria-haspopup="dialog">'
      f'<img src="{image_path(item)}" alt="{e(item["name"])}" {image_dimensions} loading="lazy">{badge}{volume}</button>'
      f'<div class="drink-content"><h4>{e(item["name"])}</h4><p class="composition">{e(item["description"])}</p><div class="drink-bottom"><strong class="price">{price(item["price_rub"])}</strong>{detail(item)}</div>{nutrients(item)}</div></article>')
def group(cid,number):
    c=next(c for c in D['categories'] if c['id']==cid)
    subtitle={'smoothies':'Фрукты, ягоды и твой ритм','protein':'Три варианта на выбор','sport':'Порционные продукты','fresh':'Каждый фреш — 250 мл','drinks':'Кофе, чай и любимый бамбл'}[cid]
    members=[x for x in D['items'] if x['category']==cid]
    columns=3 if cid in ['protein','fresh'] else 4
    content=f'<div class="product-grid product-grid--{cid} columns-{columns}">'+''.join(card(x) for x in members)+'</div>'
    return f'<section class="menu-group" id="menu-{cid}" data-menu-category="{cid}" aria-labelledby="title-{cid}"><div class="group-header"><h3 id="title-{cid}"><span class="group-number">{number:02}</span>{e(c["name"])}</h3><p>{subtitle}</p></div>{content}</section>'
short_names = {'smoothies':'Смузи','protein':'Протеин','sport':'Спортпит','fresh':'Фреши','drinks':'Напитки'}
grid_icon='<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" aria-hidden="true"><rect x="3" y="3" width="7" height="7" rx="2"/><rect x="14" y="3" width="7" height="7" rx="2"/><rect x="3" y="14" width="7" height="7" rx="2"/><rect x="14" y="14" width="7" height="7" rx="2"/></svg>'
filters='<button type="button" data-menu-filter="all" aria-pressed="true"><span class="filter-full">Всё меню</span><span class="filter-short">Всё</span></button>'+''.join(f'<button type="button" data-menu-filter="{c["id"]}" aria-pressed="false"><span class="filter-full">{e(c["name"])}</span><span class="filter-short">{e(short_names[c["id"]])}</span></button>' for c in D['categories'])
category_dialog='<dialog id="category-dialog" aria-labelledby="category-dialog-title"><div class="category-sheet"><div class="category-sheet-heading"><div><p>21 позиция на любой вкус</p><h2 id="category-dialog-title">Разделы меню</h2></div><button type="button" class="dialog-close" data-close-dialog aria-label="Закрыть разделы меню">×</button></div><div class="category-options"><button type="button" class="category-option category-option--all" data-menu-filter="all" aria-pressed="true"><span class="category-thumb category-thumb--all">'+grid_icon+'</span><span><strong>Всё меню</strong><small>21 позиция</small></span><span class="category-option-arrow" aria-hidden="true">↗</span></button>'
for c in D['categories']:
    members=[x for x in D['items'] if x['category']==c['id']]
    item=members[0]
    count=len(members)
    count_label=f'{count} '+('позиция' if count==1 else 'позиции' if count in [2,3,4] else 'позиций')
    category_dialog+=f'<button type="button" class="category-option" data-menu-filter="{c["id"]}" aria-pressed="false"><span class="category-thumb"><img src="{image_path(item)}" alt="" width="56" height="70" loading="lazy"></span><span><strong>{e(c["name"])}</strong><small>{count_label}</small></span><span class="category-option-arrow" aria-hidden="true">↗</span></button>'
category_dialog+='</div></div></dialog>'
story_items=[('breakfast','breakfast','На завтрак','17'),('berry','berry','Ягодный смузи','12'),('citrus','fresh-orange-grapefruit','Цитрусовый фреш','15'),('bumble','bumble','Бамбл-кофе','19')]
stories='<section class="stories-section wrap" id="stories" aria-labelledby="stories-title"><div class="section-title-row"><div><p class="eyebrow">ПОСМОТРИ. ПОПРОБУЙ. ПОВТОРИ.</p><h2 id="stories-title">ВКУСНО <br>В ДВИЖЕНИИ.</h2></div><p>Фрукты, ягоды, кофе и карамель. <br>Уже хочется попробовать?</p></div><div class="stories-track" aria-label="Видео напитков">'
for key,item_id,title,duration in story_items:
    item=next(x for x in D['items'] if x['id']==item_id)
    stories+=f'<article class="story-card"><div class="story-media"><video id="story-{key}" class="story-video" width="480" height="854" muted loop playsinline preload="none" poster="assets/stories/{key}.webp" data-video-src="assets/stories/{key}.mp4" aria-label="Видео: {e(title)}"></video><button class="story-toggle" type="button" aria-controls="story-{key}" aria-pressed="false" aria-label="Смотреть видео: {e(title)}"><span aria-hidden="true">▶</span><span data-play-label>Смотреть</span></button><span class="story-duration" aria-hidden="true">0:{duration}</span><noscript><a class="story-noscript" href="assets/stories/{key}.mp4">Смотреть видео</a></noscript></div><div class="story-caption"><h3>{e(title)}</h3><strong>{price(item["price_rub"])}</strong><button type="button" data-details="{item_id}" class="story-details" aria-haspopup="dialog">Состав и цена <span aria-hidden="true">↗</span></button></div></article>'
stories+='</div><p class="stories-hint">Листай видео вправо <span aria-hidden="true">→</span></p></section>'
sources=''.join(f'<li><a href="{e(s["url"])}" target="_blank" rel="noopener">{e(s["name"])}</a>. {e(s["note"])}</li>' for s in D['nutrition_method']['sources'])
html='''<!doctype html><html lang="ru"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#183329"><link rel="canonical" href="https://bar.liniyasporta.ru/"><title>Онлайн-меню спортбара «Линия спорта»</title><meta name="description" content="Онлайн-меню спортбара «Линия спорта»: смузи, протеин, фреши, кофе. Составы, цены и ориентировочная пищевая ценность."><link rel="icon" href="assets/favicon.svg" type="image/svg+xml"><link rel="preload" href="assets/fonts/font-4.woff2" as="font" type="font/woff2" crossorigin><link rel="stylesheet" href="styles.css"><link rel="stylesheet" href="mobile-menu.css"><script src="app.js" defer></script></head><body><a class="skip" href="#main">К содержимому</a><header class="site-header"><div class="wrap header-inner"><a class="brand" href="https://new.liniyasporta.ru/" aria-label="Линия спорта — главный сайт"><img src="assets/logo-dark.png" alt="Линия спорта" width="600" height="200"><span class="brand-label">ОНЛАЙН<br>МЕНЮ</span></a><nav class="top-nav" aria-label="Главная навигация"><a href="#menu">Меню</a><a href="#about">О баре</a><a class="club-link" href="https://new.liniyasporta.ru/#clubs">В клуб ↗</a></nav></div></header><main id="main"><section class="wrap hero" aria-labelledby="hero-title"><div class="hero-copy"><p class="eyebrow"><span class="dot" aria-hidden="true"></span>ОНЛАЙН-МЕНЮ СПОРТБАРА</p><h1 id="hero-title">ВКУС<br>ТВОЕГО<br><span>РИТМА.</span></h1><p class="hero-description">Загляни до тренировки. Останься после.<br> Любимые напитки в «Линии спорта».</p><a class="button" href="#menu">Выбрать по вкусу <span class="arrow" aria-hidden="true">↗</span></a><p class="hero-tail">Одно меню для всех трёх клубов.</p></div><div class="hero-visual"><img src="assets/hero.webp" alt="Бамбл-кофе с карамелью, ягодный смузи и апельсиновый фреш: визуализация напитков спортбара" width="1536" height="1024" fetchpriority="high"><div class="visual-sticker" aria-hidden="true"><small>ЛИНИЯ СПОРТА</small>НАПОЛНИ ДЕНЬ<br>ВКУСОМ.</div></div></section><div class="flavour-strip" aria-hidden="true"><div class="wrap"><span>СМУЗИ</span><b>✳</b><span>ПРОТЕИН</span><b>✳</b><span>ФРЕШИ</span><b class="hide-small">✳</b><span class="hide-small">КОФЕ</span></div></div><section class="menu-section wrap" id="menu" aria-labelledby="menu-title"><div class="section-title-row"><div><p class="eyebrow">МЕНЮ СПОРТБАРА</p><h2 id="menu-title">ВЫБИРАЙ <br>ПО ВКУСУ.</h2></div><p>Найди свой напиток, посмотри состав и выбери то, что хочется именно сейчас.</p></div><div class="menu-toolbar"><button class="mobile-menu-launcher" type="button" data-open-categories aria-haspopup="dialog" aria-controls="category-dialog" aria-expanded="false" aria-label="Все разделы меню">'''+grid_icon+'''</button><div class="menu-filters" role="group" aria-label="Разделы меню">'''+filters+'''</div></div><div class="nutrition-intro"><p>КБЖУ — ориентир на расчётную порцию.</p><div class="nutrition-controls"><label class="nutrition-toggle"><input type="checkbox" id="show-nutrition" checked>Показывать КБЖУ</label><button type="button" class="text-button" data-show-method>Как рассчитано</button></div></div><p id="menu-status" class="sr-only" role="status" aria-live="polite">В разделе: 21</p><noscript><p class="no-js-note">Все позиции меню доступны ниже. Для фильтров и подробностей расчёта включите JavaScript.</p></noscript>'''
html=html.replace('<section class="menu-section wrap"',stories+'<section class="menu-section wrap"')
html+=group('smoothies',1)+group('protein',2)+group('fresh',3)+group('sport',4)+group('drinks',5)
html+='''<aside class="nutrition-note"><strong>О пищевой ценности</strong><p>Знак ≈ означает оценку, а не лабораторный анализ. Для смузи выбраны расчётные граммовки, для протеина — 30 г порошка на воде, для гейнера — 50 г на воде. Это ориентиры, которые нужно сверить с рецептурами бара. В бамбл-кофе учтено 15 мл карамельного сиропа. Молоко и дополнительные добавки меняют КБЖУ.</p><p>Для BCAA, креатина, предтрена и фруктового чая цифры уточняются по конкретному продукту или рецептуре. Отсутствие значений не означает нулевую калорийность.</p><details><summary>Справочные источники и допущения</summary><p>Этикетки производителей использованы только как аналоги для расчёта. Марки фактических продуктов клуба не подтверждены.</p><ul class="source-list">'''+sources+'''</ul></details></aside></section><section class="about" id="about"><div class="wrap about-grid"><div><p class="eyebrow">ТРИ КЛУБА. ОДНО МЕНЮ.</p><h2>ОСТАНЬСЯ<br>НА ВКУСНОЕ.</h2></div><div><p>Смузи с фруктами, прохладный фреш или чашка кофе. Выбирай любимое и добавляй приятную паузу в свой день.</p><p class="about-rule">Во всех трёх клубах действует одно меню. Закажи на баре — до тренировки, после неё или просто по настроению.<br><a href="https://new.liniyasporta.ru/#clubs">Адреса клубов ↗</a></p></div></div></section></main><footer class="site-footer"><div class="wrap"><div class="footer-inner"><a href="https://new.liniyasporta.ru/" aria-label="Линия спорта — главный сайт"><img src="assets/logo-dark.png" alt="Линия спорта" width="600" height="200"></a><p>Спортбар «Линия спорта»<br>Безалкогольное меню · Симферополь</p><a href="https://docs.liniyasporta.ru/">Документы клуба ↗</a></div><p class="visual-note">Цены перенесены из меню клуба от 29.10.2026.</p></div></footer><dialog id="item-dialog" aria-labelledby="dialog-item-name"><div class="dialog-inner"><div class="dialog-header"><div><p class="dialog-label" data-dialog-category></p><h2 id="dialog-item-name" data-dialog-name></h2></div><button class="dialog-close" type="button" data-close-dialog aria-label="Закрыть">×</button></div><p data-dialog-composition></p><p class="dialog-price" data-dialog-price></p><p class="dialog-label" data-dialog-nutrition-label>Ориентир на расчётную порцию</p><div class="dialog-nutrition" data-dialog-nutrition><div><b data-value="kcal"></b>ккал</div><div><b data-value="protein"></b>белки, г</div><div><b data-value="fat"></b>жиры, г</div><div><b data-value="carbs"></b>углеводы, г</div></div><p data-dialog-assumption class="dialog-assumption"></p><p data-dialog-estimate-note class="dialog-assumption">Граммовки для расчёта предварительные и не являются подтверждённой рецептурой клуба.</p></div></dialog><dialog id="method-dialog" aria-labelledby="method-title"><div class="dialog-inner"><div class="dialog-header"><h2 id="method-title">Как рассчитаны КБЖУ</h2><button class="dialog-close" type="button" data-close-dialog aria-label="Закрыть">×</button></div><div class="method-content"><p>В исходном меню перечислены составы, но не указаны граммовки смузи, дозировки порошков и основа напитков. Поэтому значения на сайте — предварительная оценка.</p><ul><li>Смузи: продукты взвешены условно; все граммовки можно увидеть в карточке.</li><li>Протеин: 30 г порошка на воде. Гейнер: 50 г на воде. Использованы этикетки аналогов, а не подтверждённых продуктов бара.</li><li>Фреши: 250 мл ≈ 260 г сока. В смесях взяты равные доли.</li><li>Сахар, мёд и молоко дополнительно не включены. Для бамбл-кофе отдельно учтено 15 мл карамельного сиропа.</li><li>Калории округлены до 5 ккал, БЖУ — до целого грамма. Для небольших порций ненулевая энергия округлена до 5 ккал.</li></ul><p>После уточнения рецептур и этикеток значения можно пересчитать. Источники приведены внизу меню.</p></div></div></dialog><script type="application/json" id="menu-data">'''+json.dumps(D,ensure_ascii=False).replace('</', '<' + chr(92) + '/')+'''</script></body></html>'''
html=html.replace('<script type="application/json" id="menu-data">',category_dialog+'<script type="application/json" id="menu-data">')
for filename in ['styles.css','mobile-menu.css','app.js']:
    digest=hashlib.sha256((SITE/filename).read_bytes()).hexdigest()[:12]
    html=html.replace(filename+'\"',filename+'?v='+digest+'\"')
(SITE/'index.html').write_text(html)
print('Rendered complete bar menu: 21 static image cards, 5 categories, individual nutrition details.')
